import{_ as e,o,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Analizador de espacio","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/space-analyzer.md","filePath":"es-ES/user-guide/space-analyzer.md","lastUpdated":1786468666000}'),i={name:"es-ES/user-guide/space-analyzer.md"};function l(n,a,t,d,c,u){return o(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="analizador-de-espacio" tabindex="-1">Analizador de espacio <a class="header-anchor" href="#analizador-de-espacio" aria-label="Permalink to &quot;Analizador de espacio&quot;">​</a></h1><p>El Analizador de espacio convierte los índices de archivos existentes de Lertaro en una vista rápida similar a SpaceSniffer. No analiza los discos, por lo que se abre con rapidez incluso si varias unidades contienen millones de elementos.</p><h2 id="abrir-el-analizador" tabindex="-1">Abrir el analizador <a class="header-anchor" href="#abrir-el-analizador" aria-label="Permalink to &quot;Abrir el analizador&quot;">​</a></h2><p>Haz clic con el botón derecho en el icono de Lertaro de la bandeja y elige <strong>Analizador de espacio</strong>. El primer nivel muestra todos los índices cargados actualmente por Lertaro. Haz doble clic con el botón izquierdo en una unidad o carpeta para entrar; usa la flecha hacia arriba o cualquier elemento de la ruta de navegación para volver.</p><h2 id="leer-y-usar-la-vista" tabindex="-1">Leer y usar la vista <a class="header-anchor" href="#leer-y-usar-la-vista" aria-label="Permalink to &quot;Leer y usar la vista&quot;">​</a></h2><ul><li>El mapa de árbol de la izquierda asigna más superficie a los elementos grandes. Los tonos claros y oscuros indican el tamaño relativo, mientras que los bordes distinguen las carpetas de los archivos.</li><li>La lista de la derecha muestra los mismos elementos ordenados por tamaño descendente. Seleccionar un elemento en una vista también lo resalta en la otra.</li><li>Haz clic con el botón derecho en una tarjeta o fila para abrir el mismo menú de acciones de los resultados de búsqueda, con opciones para abrir, localizar, copiar y ejecutar las acciones de plugins aplicables.</li><li>La información emergente solo aparece cuando el nombre o el tamaño están truncados.</li></ul><h2 id="que-se-cuenta" tabindex="-1">Qué se cuenta <a class="header-anchor" href="#que-se-cuenta" aria-label="Permalink to &quot;Qué se cuenta&quot;">​</a></h2><p>Solo se incluyen los elementos que ya existen en los índices habilitados de Lertaro, y el analizador nunca recorre el sistema de archivos para completar lo que falta. El contenido excluido o no indexado está ausente; los elementos ocultos y del sistema no se muestran individualmente, aunque su tamaño todavía puede contribuir al total de una carpeta antecesora visible.</p><p>Los tamaños son tamaños lógicos de archivo, no espacio asignado en disco. Los totales de las carpetas incluyen sus descendientes indexados y los datos con vínculos físicos solo se cuentan una vez, por lo que los resultados pueden diferir del Explorador de Windows o de un analizador de disco a nivel de sectores.</p><p>Al abrir la ventana o pulsar <strong>Actualizar</strong> se consulta el estado más reciente de los índices en memoria, incluidos los cambios de archivos que ya hayan recibido los monitores activos. El analizador no abre ni vuelve a cargar por separado los archivos de caché del índice. Al cerrar la ventana se liberan los elementos renderizados y las cachés de interfaz compartidas.</p>',10)])])}const h=e(i,[["render",l]]);export{m as __pageData,h as default};
